import importlib

mods = ["pypdf", "PyPDF2", "reportlab", "pdfplumber", "pypdfium2", "fitz", "pdf2image", "PIL"]
for m in mods:
    try:
        mod = importlib.import_module(m)
        print(f"{m}: AVAILABLE (version: {getattr(mod, '__version__', 'unknown')})")
    except Exception as e:
        print(f"{m}: NOT AVAILABLE ({e})")

# Also check command-line tools
import shutil
for tool in ["pdftotext", "qpdf", "pdftk", "pdfimages"]:
    print(f"{tool}: {shutil.which(tool)}")

import sys, site, os, glob

print("Python executable:", sys.executable)
print("Python version:", sys.version)
print("sys.path:")
for p in sys.path:
    print("  ", p)
print("\nsite-packages contents (top-level dirs/files):")
for sp in site.getsitepackages() + [site.getusersitepackages()]:
    if os.path.isdir(sp):
        print(f"  [{sp}]")
        for name in sorted(os.listdir(sp)):
            print("    ", name)

